import React, { useState, useMemo, useRef, useEffect } from "react";
import {
  Sun, Moon, Plus, CalendarDays, Settings, Clock, ChevronRight, ChevronLeft,
  Pencil, Repeat, Trash2, Copy, X, Check, MapPin, User, MoreHorizontal, LayoutList
} from "lucide-react";
import * as api from "./api.js";

const CHARACTER_IMG = "data:image/png;base64,";


/* ============================ Design tokens ============================ */
const T = {
  primary: "#1677FF",
  success: "#1DB954",
  bg: "#F7F8FA",
  card: "#FFFFFF",
  text: "#111827",
  text2: "#6B7280",
  divider: "#E5E7EB",
  danger: "#EF4444",
  warning: "#F59E0B",
  rCard: 24, rBtn: 18, rInput: 16, rFloat: 999,
  shadow: "0 8px 32px rgba(17,24,39,0.06)",
  shadowSoft: "0 4px 20px rgba(17,24,39,0.05)",
  font: "'Rubik','Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif",
};

/* ============================ Date helpers ============================ */
const DAYS = ["ראשון", "שני", "שלישי", "רביעי", "חמישי", "שישי", "שבת"];
const DAYS_SHORT = ["א׳", "ב׳", "ג׳", "ד׳", "ה׳", "ו׳", "ש׳"];
const MONTHS = ["ינואר", "פברואר", "מרץ", "אפריל", "מאי", "יוני", "יולי", "אוגוסט", "ספטמבר", "אוקטובר", "נובמבר", "דצמבר"];

const pad = (n) => String(n).padStart(2, "0");
const ymd = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const parseYMD = (s) => { const [y, m, dd] = s.split("-").map(Number); return new Date(y, m - 1, dd); };
const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };
const startOfWeek = (d) => addDays(d, -d.getDay()); // Sunday
const toMin = (t) => { const [h, m] = t.split(":").map(Number); return h * 60 + m; };
const sameYMD = (a, b) => ymd(a) === ymd(b);
const longDate = (d) => `${DAYS[d.getDay()]} · ${d.getDate()} ב${MONTHS[d.getMonth()]}`;
const shortDate = (d) => `${d.getDate()} ב${MONTHS[d.getMonth()]}`;

/* ============================ Seed data ============================ */
const seedWorkplaces = () => ([
  {
    id: "w1", name: "דובנוב", accent: T.primary,
    shiftTypes: [
      { id: "w1m", name: "בוקר", kind: "morning", starts: ["07:00", "08:00", "09:00", "10:00", "11:00"], ends: ["14:00", "15:00", "16:00", "17:00"] },
      { id: "w1e", name: "ערב", kind: "evening", starts: ["17:00", "18:00", "19:00"], ends: ["21:00", "22:00", "23:00"] },
    ],
  },
  {
    id: "w2", name: "אייסטור", accent: T.success,
    shiftTypes: [
      { id: "w2m", name: "בוקר", kind: "morning", starts: ["09:15", "09:30"], ends: ["15:00", "15:30"] },
      { id: "w2e", name: "ערב", kind: "evening", starts: ["15:00"], ends: ["21:30", "22:30"] },
    ],
  },
]);

const seedShifts = () => {
  // Start with a clean schedule — no pre-populated shifts.
  // Workplaces and their shift-type/hour definitions remain (see seedWorkplaces).
  return [];
};

/* ============================ Small UI atoms ============================ */
const Chip = ({ active, danger, children, onClick, style }) => (
  <button onClick={onClick}
    style={{
      border: "none", cursor: "pointer", fontFamily: T.font,
      padding: "10px 16px", borderRadius: T.rInput, fontSize: 15,
      fontWeight: active ? 600 : 500, minHeight: 44,
      background: active ? (danger ? T.danger : T.primary) : "#EEF1F5",
      color: active ? "#fff" : T.text, transition: "all .18s ease",
      ...style,
    }}>
    {children}
  </button>
);

const ShiftIcon = ({ kind, size = 18, color }) =>
  kind === "morning"
    ? <Sun size={size} color={color || T.warning} strokeWidth={2} />
    : <Moon size={size} color={color || T.primary} strokeWidth={2} />;

/* ============================ Bottom Sheet ============================ */
function Sheet({ title, onClose, onBack, closing, children, maxHeight = "88%" }) {
  return (
    <div dir="rtl" style={{ position: "fixed", inset: 0, zIndex: 50 }}>
      <div onClick={onClose}
        style={{ position: "absolute", inset: 0, background: "rgba(17,24,39,0.35)",
          animation: closing ? "fadeOut .2s ease forwards" : "fadeIn .2s ease" }} />
      <div style={{
        position: "absolute", left: 0, right: 0, bottom: 0, width: "100%", maxWidth: 480, margin: "0 auto", maxHeight,
        boxSizing: "border-box", overflowX: "hidden",
        background: T.card, borderTopLeftRadius: 28, borderTopRightRadius: 28,
        boxShadow: "0 -8px 40px rgba(17,24,39,0.14)", display: "flex", flexDirection: "column",
        animation: closing ? "sheetOut .22s cubic-bezier(.32,.72,0,1) forwards" : "sheetIn .28s cubic-bezier(.32,.72,0,1)",
      }}>
        <div style={{ display: "flex", justifyContent: "center", paddingTop: 10 }}>
          <div style={{ width: 40, height: 5, borderRadius: 999, background: T.divider }} />
        </div>
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 10, padding: "10px 20px 6px" }}>
          <div style={{ flex: 1, minWidth: 0, display: "flex", alignItems: "flex-start", gap: 10 }}>
            {onBack && (
              <button onClick={onBack} aria-label="חזרה" style={{ flex: "0 0 auto", marginTop: 1, border: "none", background: "#F0F2F5", borderRadius: 999, width: 34, height: 34, display: "grid", placeItems: "center", cursor: "pointer" }}>
                <ChevronRight size={18} color={T.text} />
              </button>
            )}
            <span style={{ flex: 1, minWidth: 0, fontSize: 20, fontWeight: 700, color: T.text, overflowWrap: "anywhere" }}>{title}</span>
          </div>
          <button onClick={onClose} aria-label="סגירה" style={{ flex: "0 0 auto", marginTop: 2, border: "none", background: "#F0F2F5", borderRadius: 999, width: 34, height: 34, display: "grid", placeItems: "center", cursor: "pointer" }}>
            <X size={18} color={T.text2} />
          </button>
        </div>
        <div style={{ overflowY: "auto", overflowX: "hidden", padding: "6px 20px calc(26px + env(safe-area-inset-bottom, 0px))" }}>{children}</div>
      </div>
    </div>
  );
}

const PrimaryBtn = ({ children, onClick, disabled }) => (
  <button onClick={onClick} disabled={disabled}
    style={{
      width: "100%", minHeight: 52, border: "none", borderRadius: T.rBtn,
      background: disabled ? "#B9C2CC" : T.primary, color: "#fff",
      fontFamily: T.font, fontSize: 17, fontWeight: 600, cursor: disabled ? "default" : "pointer",
      transition: "background .18s ease", boxShadow: disabled ? "none" : "0 6px 18px rgba(22,119,255,0.28)",
    }}>{children}</button>
);

const SecondaryBtn = ({ children, onClick, danger }) => (
  <button onClick={onClick}
    style={{
      width: "100%", minHeight: 50, borderRadius: T.rBtn, cursor: "pointer",
      background: "#fff", border: `1.5px solid ${danger ? "#F5C6C6" : T.divider}`,
      color: danger ? T.danger : T.text, fontFamily: T.font, fontSize: 16, fontWeight: 600,
    }}>{children}</button>
);

const SectionLabel = ({ children }) => (
  <div style={{ fontSize: 14, fontWeight: 600, color: T.text2, margin: "18px 2px 10px" }}>{children}</div>
);

/* ============================ Mini calendar (inline picker) ============================ */
function MiniCalendar({ value, onPick }) {
  const [off, setOff] = useState(0);
  const base = new Date(); base.setDate(1); base.setMonth(base.getMonth() + off);
  const year = base.getFullYear(), month = base.getMonth();
  const firstDay = new Date(year, month, 1).getDay();
  const days = new Date(year, month + 1, 0).getDate();
  const cells = [...Array(firstDay).fill(null), ...Array.from({ length: days }, (_, i) => new Date(year, month, i + 1))];
  return (
    <div style={{ background: "#F7F8FA", borderRadius: T.rInput, padding: 14, marginTop: 10 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
        <button onClick={() => setOff(off + 1)} style={miniNav}><ChevronRight size={18} color={T.text2} /></button>
        <span style={{ fontSize: 15, fontWeight: 700 }}>{MONTHS[month]} {year}</span>
        <button onClick={() => setOff(off - 1)} style={miniNav}><ChevronLeft size={18} color={T.text2} /></button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7,1fr)", marginBottom: 4 }}>
        {["א", "ב", "ג", "ד", "ה", "ו", "ש"].map((d) => (
          <div key={d} style={{ textAlign: "center", fontSize: 11, fontWeight: 600, color: T.text2 }}>{d}</div>
        ))}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7,1fr)", gap: 2 }}>
        {cells.map((d, i) => {
          if (!d) return <div key={i} />;
          const iso = ymd(d);
          const sel = value === iso;
          const isToday = sameYMD(d, new Date());
          return (
            <button key={i} onClick={() => onPick(iso)}
              style={{
                aspectRatio: "1", borderRadius: 10, cursor: "pointer", border: "none",
                background: sel ? T.primary : "transparent", fontFamily: T.font,
                color: sel ? "#fff" : isToday ? T.primary : T.text, fontWeight: sel || isToday ? 700 : 500, fontSize: 14,
              }}>{d.getDate()}</button>
          );
        })}
      </div>
    </div>
  );
}
const miniNav = { border: "none", background: "#fff", borderRadius: 999, width: 30, height: 30, display: "grid", placeItems: "center", cursor: "pointer" };

/* ============================ Shift editor sheet ============================ */
function ShiftSheet({ mode, initial, fixedDate, workplaces, shifts, onClose, closing, onSave, onDelete }) {
  const [date, setDate] = useState(initial?.date || ymd(new Date()));
  const [wpId, setWpId] = useState(initial?.workplaceId || null);
  const [stId, setStId] = useState(initial?.shiftTypeId || null);
  const [start, setStart] = useState(initial?.start || null);
  const [end, setEnd] = useState(initial?.end || null);
  const [warn, setWarn] = useState(null);       // time-order warning
  const [overlap, setOverlap] = useState(false); // overlap confirm gate
  const [confirmDel, setConfirmDel] = useState(false);
  const [changedNote, setChangedNote] = useState(false);
  const [showPicker, setShowPicker] = useState(false);

  const wp = workplaces.find((w) => w.id === wpId);
  const st = wp?.shiftTypes.find((s) => s.id === stId);
  const dObj = parseYMD(date);

  // When workplace/shift changes, keep the time only if still valid.
  const applyWp = (id) => {
    setWpId(id); const nw = workplaces.find((w) => w.id === id);
    const keep = nw?.shiftTypes.find((s) => s.name === st?.name) || nw?.shiftTypes[0];
    setStId(keep?.id || null);
    reconcileTimes(keep);
  };
  const applySt = (id) => { setStId(id); reconcileTimes(wp?.shiftTypes.find((s) => s.id === id)); };
  const reconcileTimes = (nst) => {
    if (!nst) { setStart(null); setEnd(null); return; }
    if (start && !nst.starts.includes(start)) { setStart(null); setChangedNote(true); }
    if (end && !nst.ends.includes(end)) { setEnd(null); setChangedNote(true); }
  };

  // Dynamic blue title: "משמרת ערב · יום ראשון, 26 ביולי · דובנוב"
  const verb = mode === "edit" ? "עריכת" : mode === "replace" ? "החלפת" : "הוספת";
  const titleLine1 = `${st ? `משמרת ${st.name}` : `${verb} משמרת`} · יום ${DAYS[dObj.getDay()]}, ${shortDate(dObj)}${wp ? ` · ${wp.name}` : ""}`;
  const titleSig = `${titleLine1}|${start || ""}|${end || ""}`;
  const titleNode = (
    <div key={titleSig} style={{ lineHeight: 1.35, animation: "titleFade .22s ease both" }}>
      <div style={{ fontSize: 17, fontWeight: 700, color: T.primary }}>{titleLine1}</div>
      {start && end && (
        <div style={{ fontSize: 22, fontWeight: 700, color: T.primary, direction: "ltr", textAlign: "right", marginTop: 2 }}>
          {start}–{end}
        </div>
      )}
    </div>
  );

  const quickDays = useMemo(() => [0, 1, 2].map((n) => addDays(new Date(), n)), []);

  const doSave = (force) => {
    setWarn(null);
    if (!wp || !st || !start || !end) return;
    if (toMin(end) <= toMin(start)) { setWarn("שעת הסיום חייבת להיות אחרי שעת ההתחלה"); return; }
    if (!force) {
      const clash = shifts.some((s) =>
        s.id !== initial?.id && s.date === date &&
        toMin(start) < toMin(s.end) && toMin(s.start) < toMin(end));
      if (clash) { setOverlap(true); return; }
    }
    onSave({ id: initial?.id, date, workplaceId: wpId, shiftTypeId: stId, start, end });
  };

  const canSave = wp && st && start && end;

  return (
    <Sheet title={titleNode} onClose={onClose} closing={closing}>
      {/* date — hidden entirely when the day is fixed (added for a specific day) */}
      {!fixedDate && (<>
        <SectionLabel>יום</SectionLabel>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          {quickDays.map((d, i) => (
            <Chip key={i} active={!showPicker && date === ymd(d)} onClick={() => { setDate(ymd(d)); setShowPicker(false); }}>
              {i === 0 ? "היום" : i === 1 ? "מחר" : DAYS[d.getDay()]}
            </Chip>
          ))}
          <Chip active={showPicker || !quickDays.some((d) => ymd(d) === date)} onClick={() => setShowPicker((v) => !v)}
            style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
            <CalendarDays size={16} color={(showPicker || !quickDays.some((d) => ymd(d) === date)) ? "#fff" : T.text2} />
            {!quickDays.some((d) => ymd(d) === date) ? shortDate(dObj) : "תאריך"}
          </Chip>
        </div>
        <div style={{
          maxHeight: showPicker ? 340 : 0, opacity: showPicker ? 1 : 0, overflow: "hidden",
          transition: "max-height .32s cubic-bezier(.32,.72,0,1), opacity .25s ease",
        }}>
          <MiniCalendar value={date} onPick={(iso) => { setDate(iso); setShowPicker(false); }} />
        </div>
      </>)}

      {/* workplace */}
      <SectionLabel>מקום עבודה</SectionLabel>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
        {workplaces.map((w) => (
          <button key={w.id} onClick={() => applyWp(w.id)}
            style={{
              textAlign: "start", cursor: "pointer", padding: "16px 16px", borderRadius: T.rInput,
              background: wpId === w.id ? "#F0F7FF" : "#F7F8FA",
              border: `1.5px solid ${wpId === w.id ? T.primary : "transparent"}`,
              display: "flex", alignItems: "center", gap: 10,
              transition: "background .2s ease, border-color .2s ease",
            }}>
            <span style={{ width: 10, height: 10, borderRadius: 999, background: w.accent }} />
            <span style={{ fontSize: 17, fontWeight: 600, color: T.text }}>{w.name}</span>
          </button>
        ))}
      </div>

      {/* shift type */}
      {wp && (<div key={"st-block-" + wp.id} style={{ animation: "revealIn .28s cubic-bezier(.32,.72,0,1) both" }}>
        <SectionLabel>סוג משמרת</SectionLabel>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          {wp.shiftTypes.map((s) => (
            <Chip key={s.id} active={stId === s.id} onClick={() => applySt(s.id)}
              style={{ display: "inline-flex", alignItems: "center", gap: 7 }}>
              <ShiftIcon kind={s.kind} size={16} color={stId === s.id ? "#fff" : undefined} />
              {s.name}
            </Chip>
          ))}
        </div>
      </div>)}

      {/* times */}
      {st && (<div key={"time-block-" + st.id} style={{ animation: "revealIn .28s cubic-bezier(.32,.72,0,1) both" }}>
        <SectionLabel>שעת התחלה</SectionLabel>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          {st.starts.map((t) => (
            <Chip key={t} active={start === t} onClick={() => { setStart(t); setWarn(null); setOverlap(false); }}>{t}</Chip>
          ))}
        </div>
        <SectionLabel>שעת סיום</SectionLabel>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          {st.ends.map((t) => (
            <Chip key={t} active={end === t} onClick={() => { setEnd(t); setWarn(null); setOverlap(false); }}>{t}</Chip>
          ))}
        </div>
      </div>)}

      {changedNote && (!start || !end) && (
        <div style={{ marginTop: 12, fontSize: 13, color: T.warning, fontWeight: 500, animation: "revealIn .22s ease both" }}>
          יש לבחור שעה המתאימה למשמרת החדשה
        </div>
      )}

      {warn && <div style={{ marginTop: 14, color: T.danger, fontSize: 14, fontWeight: 500, animation: "revealIn .22s ease both" }}>{warn}</div>}

      {overlap ? (
        <div style={{ marginTop: 18, background: "#FFF7ED", border: `1px solid #FCE4C4`, borderRadius: T.rInput, padding: 16, animation: "revealIn .26s cubic-bezier(.32,.72,0,1) both" }}>
          <div style={{ fontSize: 15, fontWeight: 600, color: T.text, marginBottom: 12 }}>
            המשמרת חופפת למשמרת אחרת שכבר נקבעה
          </div>
          <div style={{ display: "flex", gap: 10 }}>
            <button onClick={() => setOverlap(false)} style={btnGhost}>חזרה לעריכה</button>
            <button onClick={() => doSave(true)} style={{ ...btnGhost, background: T.warning, color: "#fff", border: "none" }}>שמירה בכל זאת</button>
          </div>
        </div>
      ) : (
        <div style={{ marginTop: 22, display: "flex", flexDirection: "column", gap: 12 }}>
          <PrimaryBtn onClick={() => doSave(false)} disabled={!canSave}>
            {mode === "add" ? "שמירת משמרת" : "שמירת שינויים"}
          </PrimaryBtn>
          {mode !== "add" && !confirmDel && (
            <SecondaryBtn danger onClick={() => setConfirmDel(true)}>מחיקת המשמרת</SecondaryBtn>
          )}
          {confirmDel && (
            <div style={{ background: "#FEF2F2", borderRadius: T.rInput, padding: 16, animation: "revealIn .24s cubic-bezier(.32,.72,0,1) both" }}>
              <div style={{ fontSize: 15, fontWeight: 600, color: T.text, marginBottom: 12 }}>
                למחוק את המשמרת ביום {DAYS[parseYMD(date).getDay()]}?
              </div>
              <div style={{ display: "flex", gap: 10 }}>
                <button onClick={() => setConfirmDel(false)} style={btnGhost}>ביטול</button>
                <button onClick={() => onDelete(initial.id)} style={{ ...btnGhost, background: T.danger, color: "#fff", border: "none" }}>מחיקה</button>
              </div>
            </div>
          )}
        </div>
      )}
    </Sheet>
  );
}
const btnGhost = { flex: 1, minHeight: 46, borderRadius: T.rBtn, border: `1.5px solid ${T.divider}`, background: "#fff", fontFamily: T.font, fontSize: 15, fontWeight: 600, color: T.text, cursor: "pointer" };

/* ============================ Duplicate sheet ============================ */
function DuplicateSheet({ source, workplaces, onClose, closing, onConfirm }) {
  const [picked, setPicked] = useState([]);
  const wp = workplaces.find((w) => w.id === source.workplaceId);
  const st = wp?.shiftTypes.find((s) => s.id === source.shiftTypeId);
  const week = useMemo(() => {
    const sow = startOfWeek(parseYMD(source.date));
    return Array.from({ length: 7 }, (_, i) => addDays(sow, i)).filter((d) => ymd(d) !== source.date);
  }, [source]);
  const toggle = (iso) => setPicked((p) => p.includes(iso) ? p.filter((x) => x !== iso) : [...p, iso]);

  return (
    <Sheet title="שכפול משמרת" onClose={onClose} closing={closing} maxHeight="70%">
      <div style={{ background: "#F7F8FA", borderRadius: T.rInput, padding: "14px 16px", marginTop: 4 }}>
        <div style={{ fontSize: 16, fontWeight: 600, display: "flex", alignItems: "center", gap: 8 }}>
          <span style={{ width: 8, height: 8, borderRadius: 999, background: wp.accent }} />
          {wp.name} · {st.name}
        </div>
        <div style={{ direction: "ltr", textAlign: "right", fontSize: 18, fontWeight: 700, marginTop: 4 }}>{source.start}–{source.end}</div>
      </div>
      <SectionLabel>הוספה לימים</SectionLabel>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        {week.map((d) => {
          const iso = ymd(d);
          const active = picked.includes(iso);
          return (
            <button key={iso} onClick={() => toggle(iso)} style={{
              border: "none", cursor: "pointer", fontFamily: T.font, minHeight: 58, minWidth: 56,
              padding: "8px 10px", borderRadius: T.rInput, textAlign: "center",
              background: active ? T.primary : "#EEF1F5", color: active ? "#fff" : T.text,
              transition: "all .18s ease", display: "flex", flexDirection: "column", alignItems: "center", gap: 3,
            }}>
              <span style={{ fontSize: 13, fontWeight: 600, opacity: active ? 0.85 : 0.7 }}>{DAYS_SHORT[d.getDay()]}</span>
              <span style={{ fontSize: 15, fontWeight: 700, direction: "ltr" }}>{pad(d.getDate())}/{pad(d.getMonth() + 1)}</span>
            </button>
          );
        })}
      </div>
      <div style={{ marginTop: 22 }}>
        <PrimaryBtn disabled={picked.length === 0} onClick={() => onConfirm(picked)}>
          שכפול ל־{picked.length || ""} ימים
        </PrimaryBtn>
      </div>
    </Sheet>
  );
}

/* ============================ Action menu ============================ */
function ActionMenu({ onClose, closing, onEdit, onDuplicate, onDelete }) {
  const item = (icon, label, fn, danger) => (
    <button onClick={fn} style={{
      display: "flex", alignItems: "center", gap: 14, width: "100%", padding: "16px 6px",
      background: "none", border: "none", cursor: "pointer", fontFamily: T.font, fontSize: 17,
      color: danger ? T.danger : T.text, fontWeight: 500, borderBottom: `1px solid ${T.divider}`,
    }}>{icon}{label}</button>
  );
  return (
    <Sheet title="פעולות" onClose={onClose} closing={closing} maxHeight="46%">
      {item(<Pencil size={20} color={T.text2} />, "עריכה", onEdit)}
      {item(<Copy size={20} color={T.text2} />, "שכפול ליום אחר", onDuplicate)}
      <div style={{ borderBottom: "none" }}>
        {item(<Trash2 size={20} color={T.danger} />, "מחיקה", onDelete, true)}
      </div>
    </Sheet>
  );
}

/* ============================ iOS-style wheel time picker ============================ */
function WheelColumn({ values, selected, onChange, itemHeight = 36, visibleCount = 5 }) {
  const ref = useRef(null);
  const timerRef = useRef(null);
  const padCount = Math.floor(visibleCount / 2);
  const height = itemHeight * visibleCount;

  useEffect(() => {
    const idx = Math.max(0, values.indexOf(selected));
    if (ref.current) ref.current.scrollTop = idx * itemHeight;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const settle = (idx) => {
    const clamped = Math.max(0, Math.min(values.length - 1, idx));
    if (ref.current) ref.current.scrollTo({ top: clamped * itemHeight, behavior: "smooth" });
    onChange(values[clamped]);
  };

  const handleScroll = () => {
    clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => {
      if (!ref.current) return;
      settle(Math.round(ref.current.scrollTop / itemHeight));
    }, 110);
  };

  return (
    <div style={{ position: "relative", width: 60, height }}>
      <div style={{
        position: "absolute", top: padCount * itemHeight, left: 0, right: 0, height: itemHeight,
        background: "#F0F2F5", borderRadius: 10, pointerEvents: "none",
      }} />
      <div ref={ref} onScroll={handleScroll} className="wheelcol" style={{
        position: "relative", height, overflowY: "auto", scrollSnapType: "y mandatory",
        paddingTop: padCount * itemHeight, paddingBottom: padCount * itemHeight,
      }}>
        {values.map((v, i) => (
          <div key={v} onClick={() => settle(i)} style={{
            height: itemHeight, display: "flex", alignItems: "center", justifyContent: "center",
            scrollSnapAlign: "center", cursor: "pointer", fontFamily: T.font,
            fontSize: v === selected ? 20 : 16, fontWeight: v === selected ? 700 : 400,
            color: v === selected ? T.text : T.text2, transition: "font-size .1s ease, color .1s ease",
          }}>{v}</div>
        ))}
      </div>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: itemHeight * 1.3, background: "linear-gradient(#fff, rgba(255,255,255,0))", pointerEvents: "none" }} />
      <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, height: itemHeight * 1.3, background: "linear-gradient(rgba(255,255,255,0), #fff)", pointerEvents: "none" }} />
    </div>
  );
}

function WheelTimePicker({ initial, onConfirm, onCancel }) {
  const [h, setH] = useState((initial || "09:00").split(":")[0]);
  const [m, setM] = useState((initial || "09:00").split(":")[1]);
  const hours = useMemo(() => Array.from({ length: 24 }, (_, i) => pad(i)), []);
  const mins = useMemo(() => Array.from({ length: 60 }, (_, i) => pad(i)), []);
  return (
    <div style={{ background: "#fff", borderRadius: 18, boxShadow: "0 12px 30px rgba(17,24,39,.16)", border: `1px solid ${T.divider}`, padding: "14px 16px", animation: "revealIn .22s cubic-bezier(.32,.72,0,1) both" }}>
      <div style={{ display: "flex", gap: 4, justifyContent: "center", alignItems: "center" }}>
        <WheelColumn values={hours} selected={h} onChange={setH} />
        <div style={{ fontSize: 20, fontWeight: 700, color: T.text2 }}>:</div>
        <WheelColumn values={mins} selected={m} onChange={setM} />
      </div>
      <div style={{ display: "flex", gap: 8, marginTop: 14 }}>
        <button onClick={onCancel} style={btnGhost}>ביטול</button>
        <button onClick={() => onConfirm(`${h}:${m}`)} style={{ ...btnGhost, background: T.primary, color: "#fff", border: "none" }}>הוספה</button>
      </div>
    </div>
  );
}

/* ============================ Workplace editor body ============================ */
function WorkplaceEditorBody({ workplace, onSave }) {
  const [wp, setWp] = useState(() => JSON.parse(JSON.stringify(workplace)));
  const [openPicker, setOpenPicker] = useState(null); // key of the open wheel picker, or null

  const update = (fn) => setWp((prev) => { const c = JSON.parse(JSON.stringify(prev)); fn(c); return c; });
  const addHour = (stId, field, val) => {
    if (!val || !/^\d{2}:\d{2}$/.test(val)) return;
    update((c) => { const s = c.shiftTypes.find((x) => x.id === stId); if (!s[field].includes(val)) s[field] = [...s[field], val].sort(); });
  };
  const removeHour = (stId, field, t) =>
    update((c) => { const s = c.shiftTypes.find((x) => x.id === stId); s[field] = s[field].filter((x) => x !== t); });

  const HourGroup = ({ stId, field, label }) => {
    const key = stId + "_" + field;
    const s = wp.shiftTypes.find((x) => x.id === stId);
    const isOpen = openPicker === key;
    return (
      <div style={{ marginTop: 12 }}>
        <div style={{ fontSize: 13, color: T.text2, marginBottom: 8 }}>{label}</div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          {s[field].map((t) => (
            <span key={t} style={{ display: "inline-flex", alignItems: "center", gap: 6, background: "#EEF1F5", padding: "8px 10px 8px 12px", borderRadius: T.rInput, fontSize: 14, fontWeight: 500 }}>
              {t}
              <button onClick={() => removeHour(stId, field, t)} style={{ border: "none", background: "none", cursor: "pointer", display: "grid", placeItems: "center", padding: 0 }}>
                <X size={14} color={T.text2} />
              </button>
            </span>
          ))}
          <button onClick={() => setOpenPicker(isOpen ? null : key)} style={{
            display: "inline-flex", alignItems: "center", gap: 6, background: isOpen ? T.primary : "#fff",
            color: isOpen ? "#fff" : T.primary, border: `1.5px dashed ${isOpen ? T.primary : T.divider}`,
            borderRadius: T.rInput, padding: "8px 12px", cursor: "pointer", fontFamily: T.font, fontSize: 14, fontWeight: 600,
          }}>
            <Plus size={14} /> הוספת שעה
          </button>
        </div>
        {isOpen && (
          <div style={{ marginTop: 10 }}>
            <WheelTimePicker
              initial={s[field][s[field].length - 1] || "09:00"}
              onCancel={() => setOpenPicker(null)}
              onConfirm={(val) => { addHour(stId, field, val); setOpenPicker(null); }}
            />
          </div>
        )}
      </div>
    );
  };

  const addShiftType = () => update((c) => c.shiftTypes.push({
    id: "st" + Date.now(), name: "משמרת חדשה", kind: "morning", starts: [], ends: [],
  }));

  return (
    <>
      <SectionLabel>שם מקום העבודה</SectionLabel>
      <input value={wp.name} onChange={(e) => update((c) => c.name = e.target.value)} style={inputStyle} />

      <SectionLabel>צבע</SectionLabel>
      <div style={{ display: "flex", gap: 10 }}>
        {[T.primary, T.success, "#8B5CF6", T.warning, "#EC4899"].map((c) => (
          <button key={c} onClick={() => update((x) => x.accent = c)}
            style={{ width: 34, height: 34, borderRadius: 999, background: c, border: wp.accent === c ? "3px solid #fff" : "none", boxShadow: wp.accent === c ? `0 0 0 2px ${c}` : "none", cursor: "pointer" }} />
        ))}
      </div>

      {wp.shiftTypes.map((s) => (
        <div key={s.id} style={{ marginTop: 20, background: "#F7F8FA", borderRadius: T.rInput, padding: 16 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
            <ShiftIcon kind={s.kind} size={18} />
            <input value={s.name} onChange={(e) => update((c) => c.shiftTypes.find((x) => x.id === s.id).name = e.target.value)}
              style={{ ...inputStyle, marginBottom: 0, background: "#fff", fontWeight: 600 }} />
            <button onClick={() => update((c) => c.shiftTypes = c.shiftTypes.filter((x) => x.id !== s.id))}
              style={{ border: "none", background: "#fff", borderRadius: 10, width: 40, height: 40, display: "grid", placeItems: "center", cursor: "pointer" }}>
              <Trash2 size={17} color={T.danger} />
            </button>
          </div>
          <div style={{ display: "flex", gap: 8, marginTop: 6 }}>
            {["morning", "evening"].map((k) => (
              <Chip key={k} active={s.kind === k} onClick={() => update((c) => c.shiftTypes.find((x) => x.id === s.id).kind = k)}
                style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "6px 12px", minHeight: 36 }}>
                <ShiftIcon kind={k} size={14} color={s.kind === k ? "#fff" : undefined} />{k === "morning" ? "בוקר" : "ערב"}
              </Chip>
            ))}
          </div>
          <HourGroup stId={s.id} field="starts" label="אפשרויות שעת התחלה" />
          <HourGroup stId={s.id} field="ends" label="אפשרויות שעת סיום" />
        </div>
      ))}

      <button onClick={addShiftType} style={{
        marginTop: 16, width: "100%", minHeight: 48, borderRadius: T.rBtn, cursor: "pointer",
        border: `1.5px dashed ${T.divider}`, background: "#fff", color: T.primary, fontFamily: T.font,
        fontSize: 15, fontWeight: 600, display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
      }}>
        <Plus size={18} /> הוספת סוג משמרת
      </button>

      <div style={{ marginTop: 22 }}>
        <PrimaryBtn onClick={() => onSave(wp)}>שמירת שינויים</PrimaryBtn>
      </div>
    </>
  );
}

/* ============================ Workplace info + edit sheet ============================ */
function WorkplaceInfoSheet({ workplace, shifts, isNew, onClose, closing, onSave }) {
  const [step, setStep] = useState(isNew ? "edit" : "stats");
  const [monthOff, setMonthOff] = useState(0);
  const [openRow, setOpenRow] = useState(null);

  const base = new Date(); base.setDate(1); base.setMonth(base.getMonth() + monthOff);
  const year = base.getFullYear(), month = base.getMonth();

  const monthShifts = shifts
    .filter((s) => {
      if (s.workplaceId !== workplace.id) return false;
      const d = parseYMD(s.date);
      return d.getFullYear() === year && d.getMonth() === month;
    })
    .sort((a, b) => a.date === b.date ? toMin(a.start) - toMin(b.start) : a.date < b.date ? -1 : 1);

  const totalMin = monthShifts.reduce((sum, s) => sum + (toMin(s.end) - toMin(s.start)), 0);
  const fmtDur = (min) => `${Math.floor(min / 60)}:${pad(min % 60)}`;

  const titleNode = step === "stats"
    ? (<span style={{ display: "inline-flex", alignItems: "center", gap: 9 }}>
        <span style={{ width: 11, height: 11, borderRadius: 999, background: workplace.accent }} />{workplace.name}
      </span>)
    : (isNew ? "מקום עבודה חדש" : "עריכת מקום עבודה");

  const prevMonthRef = useRef(monthOff);
  const mdir = monthOff > prevMonthRef.current ? 1 : monthOff < prevMonthRef.current ? -1 : 0;
  useEffect(() => { prevMonthRef.current = monthOff; }, [monthOff]);
  const monthAnim = mdir === 0 ? "none" : mdir > 0 ? "monthFwd .28s cubic-bezier(.32,.72,0,1)" : "monthBack .28s cubic-bezier(.32,.72,0,1)";

  return (
    <Sheet title={titleNode} onClose={onClose} closing={closing}
      onBack={step === "edit" && !isNew ? () => setStep("stats") : undefined}>
      <div key={step} style={{ animation: `${step === "edit" ? "stepInLeft" : "stepInRight"} .26s cubic-bezier(.32,.72,0,1) both` }}>
        {step === "stats" ? (
          <>
            {/* month navigator */}
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 8 }}>
              <button onClick={() => { setMonthOff(monthOff - 1); setOpenRow(null); }} style={miniNav}><ChevronRight size={18} color={T.text2} /></button>
              <span key={"lbl" + monthOff} style={{ fontSize: 16, fontWeight: 700, animation: monthAnim }}>{MONTHS[month]} {year}</span>
              <button onClick={() => { setMonthOff(monthOff + 1); setOpenRow(null); }} style={miniNav}><ChevronLeft size={18} color={T.text2} /></button>
            </div>

            <div key={"body" + monthOff} style={{ animation: monthAnim }}>
            {/* totals */}
            <div style={{ marginTop: 14, background: "#F7F8FA", borderRadius: T.rInput, padding: "18px 20px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
              <div>
                <div style={{ fontSize: 13, color: T.text2, fontWeight: 600 }}>סה״כ שעות החודש</div>
                <div style={{ fontSize: 34, fontWeight: 700, color: workplace.accent, direction: "ltr", textAlign: "right" }}>{fmtDur(totalMin)}</div>
              </div>
              <div style={{ textAlign: "center", minWidth: 64 }}>
                <div style={{ fontSize: 28, fontWeight: 700, color: T.text }}>{monthShifts.length}</div>
                <div style={{ fontSize: 12, color: T.text2 }}>משמרות</div>
              </div>
            </div>

            {/* breakdown rows */}
            <SectionLabel>פירוט משמרות</SectionLabel>
            {monthShifts.length === 0 ? (
              <div style={{ background: "#F7F8FA", borderRadius: T.rInput, padding: "22px 0", textAlign: "center", color: T.text2, fontSize: 14 }}>
                אין משמרות בחודש זה
              </div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {monthShifts.map((s, i) => {
                  const st = workplace.shiftTypes.find((x) => x.id === s.shiftTypeId);
                  const d = parseYMD(s.date);
                  const open = openRow === s.id;
                  const min = toMin(s.end) - toMin(s.start);
                  return (
                    <button key={s.id} onClick={() => setOpenRow(open ? null : s.id)}
                      style={{ textAlign: "start", background: "#fff", border: `1px solid ${T.divider}`, borderRadius: 14, padding: "12px 14px", cursor: "pointer", fontFamily: T.font, animation: `revealIn .3s cubic-bezier(.32,.72,0,1) ${i * 0.05}s both` }}>
                      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                          <span style={{ width: 34, textAlign: "center" }}>
                            <div style={{ fontSize: 11, color: T.text2, fontWeight: 600 }}>{DAYS_SHORT[d.getDay()]}</div>
                            <div style={{ fontSize: 18, fontWeight: 700, color: T.text }}>{d.getDate()}</div>
                          </span>
                          <span>
                            <div style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 14, fontWeight: 600, color: T.text }}>
                              {st && <ShiftIcon kind={st.kind} size={14} />}{st ? st.name : "משמרת"}
                            </div>
                            <div style={{ fontSize: 13, color: T.text2, direction: "ltr", textAlign: "right" }}>{s.start}–{s.end}</div>
                          </span>
                        </div>
                        <span style={{ fontSize: 15, fontWeight: 700, color: workplace.accent, direction: "ltr" }}>{fmtDur(min)}</span>
                      </div>
                      {open && (
                        <div style={{ marginTop: 10, paddingTop: 10, borderTop: `1px solid ${T.divider}`, fontSize: 13, color: T.text2, animation: "revealIn .2s ease both" }}>
                          {longDate(d)} · משך {fmtDur(min)} שעות{st ? ` · משמרת ${st.name}` : ""}
                        </div>
                      )}
                    </button>
                  );
                })}
              </div>
            )}
            </div>

            <div style={{ marginTop: 22 }}>
              <SecondaryBtn onClick={() => setStep("edit")}>
                <span style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 8 }}>
                  <Pencil size={16} color={T.text} /> עריכת מקום העבודה
                </span>
              </SecondaryBtn>
            </div>
          </>
        ) : (
          <WorkplaceEditorBody workplace={workplace} onSave={onSave} />
        )}
      </div>
    </Sheet>
  );
}
const inputStyle = {
  width: "100%", boxSizing: "border-box", background: "#F7F8FA", border: "none",
  borderRadius: T.rInput, padding: "14px 16px", fontFamily: T.font, fontSize: 16,
  color: T.text, marginBottom: 4, outline: "none",
};

/* ============================ Shift card ============================ */
function ShiftCard({ shift, wp, st, index = 0, onEdit, onDuplicate, onMenu }) {
  const pressTimer = useRef(null);
  const start = () => { pressTimer.current = setTimeout(onMenu, 500); };
  const clear = () => clearTimeout(pressTimer.current);
  const [open, setOpen] = useState(false);
  return (
    <div onContextMenu={(e) => { e.preventDefault(); onMenu(); }}
      onTouchStart={start} onTouchEnd={clear} onTouchMove={clear}
      onClick={() => setOpen((v) => !v)}
      style={{
        background: T.card, borderRadius: T.rCard, boxShadow: T.shadow, padding: "14px 16px",
        borderInlineStart: `3px solid ${wp.accent}`, animation: `cardIn .34s cubic-bezier(.32,.72,0,1) ${index * 0.07}s both`,
        cursor: "pointer",
      }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span style={{ fontSize: 18, fontWeight: 700, color: T.text }}>{wp.name}</span>
        <button onClick={(e) => { e.stopPropagation(); onMenu(); }} style={{ flex: "0 0 auto", border: "none", background: "#F5F6F8", borderRadius: 999, width: 32, height: 32, display: "grid", placeItems: "center", cursor: "pointer" }}>
          <MoreHorizontal size={17} color={T.text2} />
        </button>
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 4 }}>
        <span style={{ fontSize: 13, color: T.text2, display: "inline-flex", alignItems: "center", gap: 5, fontWeight: 500 }}>
          <ShiftIcon kind={st.kind} size={13} /> משמרת {st.name}
        </span>
        <span style={{ fontSize: 18, fontWeight: 700, color: T.text, direction: "ltr" }}>{shift.start}–{shift.end}</span>
      </div>
      <div style={{
        maxHeight: open ? 60 : 0, opacity: open ? 1 : 0, overflow: "hidden",
        transition: "max-height .28s cubic-bezier(.32,.72,0,1), opacity .22s ease, margin-top .28s cubic-bezier(.32,.72,0,1)",
        marginTop: open ? 12 : 0,
      }}>
        <div style={{ display: "flex", gap: 10, borderTop: `1px solid ${T.divider}`, paddingTop: 12 }}>
          <button onClick={(e) => { e.stopPropagation(); onEdit(); }} style={cardAction}><Pencil size={16} color={T.text2} /> עריכה</button>
          <button onClick={(e) => { e.stopPropagation(); onDuplicate(); }} style={cardAction}><Copy size={16} color={T.text2} /> שכפול</button>
        </div>
      </div>
    </div>
  );
}
const cardAction = { flex: 1, display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 7, minHeight: 40, borderRadius: 12, border: "none", background: "#F7F8FA", color: T.text, fontFamily: T.font, fontSize: 15, fontWeight: 600, cursor: "pointer" };

/* ============================ Home screen ============================ */
function Home({ name, workplaces, shifts, weekOffset, setWeekOffset, focusDay, setFocusDay, actions, now, onOpenSettings }) {
  const wpById = (id) => workplaces.find((w) => w.id === id);
  const stById = (wid, sid) => wpById(wid)?.shiftTypes.find((s) => s.id === sid);

  const hour = now.getHours();
  const greet =
    hour >= 5 && hour < 12 ? "בוקר טוב" :
    hour >= 12 && hour < 17 ? "צהריים טובים" :
    hour >= 17 && hour < 21 ? "ערב טוב" : "לילה טוב";

  const weekStart = startOfWeek(addDays(now, weekOffset * 7));
  const week = Array.from({ length: 7 }, (_, i) => addDays(weekStart, i));

  const ongoing = useMemo(() => {
    const nowMin = now.getHours() * 60 + now.getMinutes();
    return shifts.find((s) => sameYMD(parseYMD(s.date), now) && toMin(s.start) <= nowMin && nowMin < toMin(s.end));
  }, [shifts, now]);

  const next = useMemo(() => {
    const nowMin = now.getHours() * 60 + now.getMinutes();
    return shifts
      .filter((s) => { const d = parseYMD(s.date); return d > new Date(now.getFullYear(), now.getMonth(), now.getDate()) || (sameYMD(d, now) && toMin(s.start) >= nowMin); })
      .sort((a, b) => a.date === b.date ? toMin(a.start) - toMin(b.start) : a.date < b.date ? -1 : 1)[0];
  }, [shifts, now]);

  const featured = ongoing || next;

  const remainingLabel = (s) => {
    const target = new Date(now.getFullYear(), now.getMonth(), now.getDate(), ...s.end.split(":").map(Number));
    const diff = Math.max(0, target - now); const h = Math.floor(diff / 3600000); const m = Math.floor((diff % 3600000) / 60000);
    if (h >= 1) return `נותרו ${h} שעות ו־${m} דקות`;
    return `נותרו ${m} דקות`;
  };

  const countdown = (s) => {
    const d = parseYMD(s.date); const target = new Date(d.getFullYear(), d.getMonth(), d.getDate(), ...s.start.split(":").map(Number));
    const diff = Math.max(0, target - now); const h = Math.floor(diff / 3600000); const m = Math.floor((diff % 3600000) / 60000);
    if (h >= 24) return `בעוד ${Math.round(h / 24)} ימים`;
    if (h >= 1) return `מתחילה בעוד ${h} שעות`;
    return `מתחילה בעוד ${m} דקות`;
  };

  // direction of week change → slide animation
  const prevWeekRef = useRef(weekOffset);
  const dir = weekOffset > prevWeekRef.current ? 1 : weekOffset < prevWeekRef.current ? -1 : 0;
  useEffect(() => { prevWeekRef.current = weekOffset; }, [weekOffset]);
  const weekAnim = dir === 0 ? "none" : dir > 0 ? "weekFwd .32s cubic-bezier(.32,.72,0,1)" : "weekBack .32s cubic-bezier(.32,.72,0,1)";

  // keep today's chip in view on the current week
  const todayRef = useRef(null);
  useEffect(() => {
    if (weekOffset === 0 && todayRef.current) todayRef.current.scrollIntoView({ inline: "center", block: "nearest" });
  }, [weekOffset]);

  let cardN = 0; // running index for staggered card entrance

  const featWp = featured ? wpById(featured.workplaceId) : null;
  const featSt = featured ? stById(featured.workplaceId, featured.shiftTypeId) : null;
  const featTitle = featured ? (ongoing ? featWp.name :
    `${sameYMD(parseYMD(featured.date), now) ? "היום" : sameYMD(parseYMD(featured.date), addDays(now, 1)) ? "מחר" : DAYS[parseYMD(featured.date).getDay()]} ב${featWp.name}`) : "";

  return (
    <div style={{ padding: "0 0 120px", position: "relative", overflowX: "clip", width: "100%", maxWidth: "100%" }}>
      {/* decorative soft blobs */}
      <div aria-hidden style={{
        position: "absolute", top: -20, right: -60, width: 220, height: 220, borderRadius: "50%",
        background: "radial-gradient(circle, rgba(22,119,255,0.12) 0%, rgba(22,119,255,0) 70%)",
        pointerEvents: "none", zIndex: 0,
      }} />
      <div aria-hidden style={{
        position: "absolute", top: 150, left: -70, width: 180, height: 180, borderRadius: "50%",
        background: "radial-gradient(circle, rgba(29,185,84,0.09) 0%, rgba(29,185,84,0) 70%)",
        pointerEvents: "none", zIndex: 0,
      }} />

      {/* HERO */}
      <header className="hero">
        <button onClick={onOpenSettings} aria-label="הגדרות" className="settingsButton">
          <Settings size={20} color={T.text2} strokeWidth={2} />
        </button>
        <div className="heroGrid">
          <div className="greetingBlock">
            <div className="greetingLine">היי {name} 👋</div>
            <div className="dayGreeting">{greet}</div>
            <div className="greetingSubtitle">הנה המשמרות שלך לשבוע הקרוב</div>
          </div>
          <div className="mascotWrapper">
            <img src={CHARACTER_IMG} alt="" className="mascotImage" />
          </div>
        </div>
      </header>

      {/* CURRENT SHIFT CARD */}
      <section className="currentShiftCard">
        {featured ? (<>
          <div className="cardTopRow">
            <div className="statusStack">
              <div className="statusBadge" style={{ background: ongoing ? "#EAFBF1" : "#F0F7FF", color: ongoing ? T.success : T.primary }}>
                <span className="statusDot" style={{ background: ongoing ? T.success : T.primary }} />
                {ongoing ? "אתה במשמרת עכשיו" : "המשמרת הבאה שלך"}
              </div>
              <div className="remainingText" style={{ color: ongoing ? T.success : T.primary }}>
                {ongoing ? remainingLabel(featured) : countdown(featured)}
              </div>
            </div>
          </div>
          <div className="cardMainRow">
            <div className="shiftInfo">
              <h2 className="shiftWorkplace">{featTitle}</h2>
              <div className="shiftMeta">
                <ShiftIcon kind={featSt.kind} size={16} />
                <span>{featSt.name}</span>
                <span className="metaSep">•</span>
                <span className="shiftTime" style={{ direction: "ltr" }}>{featured.start}–{featured.end}</span>
              </div>
            </div>
          </div>
        </>) : (
          <div style={{ fontSize: 16, fontWeight: 600, color: T.text }}>אין משמרות קרובות</div>
        )}
      </section>

      {/* week strip */}
      <div style={{ padding: "0 20px", position: "relative", zIndex: 2 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 24, marginBottom: 14 }}>
        <button onClick={() => setWeekOffset(weekOffset - 1)} style={navBtn}><ChevronRight size={20} color={T.text2} /></button>
        <button onClick={() => { setWeekOffset(0); setFocusDay(null); }} style={{
          border: "none", cursor: "pointer", fontFamily: T.font,
          fontSize: 15, fontWeight: weekOffset === 0 ? 700 : 600,
          color: weekOffset === 0 ? T.primary : T.text,
          padding: "6px 18px", borderRadius: 999, position: "relative", zIndex: 1,
          background: "radial-gradient(ellipse 80% 120% at center, rgba(255,255,255,0.98) 0%, rgba(255,255,255,0.9) 45%, rgba(255,255,255,0) 75%)",
          boxShadow: "0 0 24px 16px rgba(255,255,255,0.9)",
        }}>
          {weekOffset === 0 ? "השבוע" : `${shortDate(weekStart)} – ${shortDate(addDays(weekStart, 6))}`}
        </button>
        <button onClick={() => setWeekOffset(weekOffset + 1)} style={navBtn}><ChevronLeft size={20} color={T.text2} /></button>
      </div>
      <div key={"strip" + weekOffset} style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 6, paddingBottom: 4, animation: weekAnim }} className="noscroll">
        {week.map((d) => {
          const isToday = sameYMD(d, now);
          const isFocus = focusDay === ymd(d);
          const dayWpColors = [...new Set(shifts.filter((s) => s.date === ymd(d)).map((s) => s.workplaceId))]
            .map((wid) => wpById(wid)?.accent).filter(Boolean);
          return (
            <button key={ymd(d)} ref={isToday ? todayRef : null} onClick={() => setFocusDay(isFocus ? null : ymd(d))}
              style={{
                width: "100%", minWidth: 0, height: 80, padding: 0, borderRadius: 18, cursor: "pointer",
                border: isToday && !isFocus ? `2px solid ${T.primary}` : "1.5px solid transparent",
                background: isFocus ? T.primary : "#fff", boxShadow: isFocus ? "0 6px 14px rgba(22,119,255,.35)" : "0 1px 4px rgba(17,24,39,0.04)",
                display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 3,
                transition: "background .2s ease",
              }}>
              <span style={{ fontSize: 12, fontWeight: 600, color: isFocus ? "rgba(255,255,255,.9)" : (isToday ? T.primary : T.text2) }}>{DAYS_SHORT[d.getDay()]}</span>
              <span style={{ fontSize: 18, fontWeight: 700, color: isFocus ? "#fff" : (isToday ? T.primary : T.text) }}>{d.getDate()}</span>
              <span style={{ display: "flex", gap: 3, height: 5, alignItems: "center" }}>
                {dayWpColors.length > 0
                  ? dayWpColors.map((c, i) => (
                      <span key={i} style={{ width: 5, height: 5, borderRadius: 999, background: isFocus ? "#fff" : c }} />
                    ))
                  : <span style={{ width: 5, height: 5 }} />}
              </span>
            </button>
          );
        })}
      </div>

      {/* day sections */}
      <div key={"days" + weekOffset + "_" + (focusDay || "all")} style={{ marginTop: 18 }}>
      {week.filter((d) => !focusDay || ymd(d) === focusDay).map((d, di) => {
        const dayShifts = shifts.filter((s) => s.date === ymd(d)).sort((a, b) => toMin(a.start) - toMin(b.start));
        const isPast = ymd(d) < ymd(now); // date-only comparison; past days appear faded
        return (
          <div key={ymd(d)} style={{ marginTop: 8, filter: isPast ? "opacity(0.66) saturate(0.85)" : "none", transition: "filter .2s ease", animation: `cardIn .34s cubic-bezier(.32,.72,0,1) ${di * 0.06}s both` }}>
            <div style={{
              fontSize: 11, fontWeight: sameYMD(d, now) ? 700 : 600,
              color: sameYMD(d, now) ? T.primary : T.text2,
              marginBottom: 4, marginInlineStart: 2,
            }}>
              {sameYMD(d, now) ? "היום · " : ""}{longDate(d)}
            </div>
            {dayShifts.length === 0 ? (
              <button onClick={() => actions.add(ymd(d), true)} style={{
                width: "100%", minHeight: 52, background: "#fff", borderRadius: 14, border: `1.5px dashed ${T.divider}`,
                padding: "0 14px", cursor: "pointer", color: T.text2, fontFamily: T.font,
                display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8,
              }}>
                <span style={{ fontSize: 13 }}>אין משמרת ביום הזה</span>
                <span style={{ display: "inline-flex", alignItems: "center", gap: 4, color: T.primary, fontWeight: 600, fontSize: 13, whiteSpace: "nowrap" }}>
                  <Plus size={14} /> הוספת משמרת
                </span>
              </button>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {dayShifts.map((s) => (
                  <ShiftCard key={s.id} index={cardN++} shift={s} wp={wpById(s.workplaceId)} st={stById(s.workplaceId, s.shiftTypeId)}
                    onEdit={() => actions.edit(s)} onDuplicate={() => actions.duplicate(s)} onMenu={() => actions.menu(s)} />
                ))}
                <button onClick={() => actions.add(ymd(d), true)} style={{
                  width: "100%", background: "transparent", borderRadius: 16, border: `1.5px dashed ${T.divider}`,
                  padding: "9px 16px", cursor: "pointer", fontFamily: T.font,
                  display: "flex", alignItems: "center", justifyContent: "center", gap: 5,
                  color: T.primary, fontWeight: 600, fontSize: 13,
                }}>
                  <Plus size={14} /> הוספת משמרת נוספת ליום זה
                </button>
              </div>
            )}
          </div>
        );
      })}
      </div>
      </div>
    </div>
  );
}
const navBtn = { border: "none", background: "#fff", boxShadow: T.shadowSoft, borderRadius: 999, width: 38, height: 38, display: "grid", placeItems: "center", cursor: "pointer" };

/* ============================ Calendar screen ============================ */
function CalendarScreen({ workplaces, shifts, monthOffset, setMonthOffset, actions }) {
  const [sel, setSel] = useState(null);
  const base = new Date(); base.setDate(1); base.setMonth(base.getMonth() + monthOffset);
  const year = base.getFullYear(), month = base.getMonth();
  const firstDay = new Date(year, month, 1).getDay();
  const days = new Date(year, month + 1, 0).getDate();
  const cells = [...Array(firstDay).fill(null), ...Array.from({ length: days }, (_, i) => new Date(year, month, i + 1))];
  const wpById = (id) => workplaces.find((w) => w.id === id);
  const stById = (wid, sid) => wpById(wid)?.shiftTypes.find((s) => s.id === sid);
  const selShifts = sel ? shifts.filter((s) => s.date === sel).sort((a, b) => toMin(a.start) - toMin(b.start)) : [];

  const prevMonthRef = useRef(monthOffset);
  const dir = monthOffset > prevMonthRef.current ? 1 : monthOffset < prevMonthRef.current ? -1 : 0;
  useEffect(() => { prevMonthRef.current = monthOffset; setSel(null); }, [monthOffset]);
  const monthAnim = dir === 0 ? "none" : dir > 0 ? "monthFwd .3s cubic-bezier(.32,.72,0,1)" : "monthBack .3s cubic-bezier(.32,.72,0,1)";

  return (
    <div style={{ padding: "8px 20px 120px" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 12, marginBottom: 20 }}>
        <button onClick={() => setMonthOffset(monthOffset - 1)} style={navBtn}><ChevronRight size={20} color={T.text2} /></button>
        <div key={"label" + monthOffset} style={{ fontSize: 26, fontWeight: 700, animation: monthAnim }}>{MONTHS[month]} {year}</div>
        <button onClick={() => setMonthOffset(monthOffset + 1)} style={navBtn}><ChevronLeft size={20} color={T.text2} /></button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7,1fr)", marginBottom: 8 }}>
        {["א", "ב", "ג", "ד", "ה", "ו", "ש"].map((d) => (
          <div key={d} style={{ textAlign: "center", fontSize: 13, fontWeight: 600, color: T.text2 }}>{d}</div>
        ))}
      </div>
      <div key={"grid" + monthOffset} style={{ display: "grid", gridTemplateColumns: "repeat(7,1fr)", gap: 4 }}>
        {cells.map((d, i) => {
          if (!d) return <div key={i} />;
          const iso = ymd(d);
          const isToday = sameYMD(d, new Date());
          const dayShifts = shifts.filter((s) => s.date === iso);
          const isSel = sel === iso;
          return (
            <button key={i} onClick={() => setSel(isSel ? null : iso)}
              style={{
                aspectRatio: "1", borderRadius: 14, cursor: "pointer", position: "relative",
                border: isSel ? `1.5px solid ${T.primary}` : "1.5px solid transparent",
                background: isToday ? "#F0F7FF" : "#fff", display: "flex", flexDirection: "column",
                alignItems: "center", justifyContent: "center", gap: 3,
                transition: "background .18s ease, border-color .18s ease",
                animation: `cardIn .32s cubic-bezier(.32,.72,0,1) ${i * 0.022}s both`,
              }}>
              <span style={{ fontSize: 15, fontWeight: isToday ? 700 : 500, color: isToday ? T.primary : T.text }}>{d.getDate()}</span>
              <div style={{ display: "flex", gap: 3, height: 6 }}>
                {[...new Set(dayShifts.map((s) => s.workplaceId))].slice(0, 3).map((wid) => (
                  <span key={wid} style={{ width: 6, height: 6, borderRadius: 999, background: wpById(wid).accent }} />
                ))}
              </div>
            </button>
          );
        })}
      </div>

      {sel && (
        <div key={sel} style={{ marginTop: 22, animation: "revealIn .24s cubic-bezier(.32,.72,0,1) both" }}>
          <div style={{ fontSize: 14, fontWeight: 600, color: T.text2, marginBottom: 10 }}>{longDate(parseYMD(sel))}</div>
          {selShifts.length === 0 ? (
            <div style={{ background: "#fff", borderRadius: T.rCard, boxShadow: T.shadowSoft, padding: "20px 0", textAlign: "center", color: T.text2 }}>אין משמרת ביום הזה</div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
              {selShifts.map((s, i) => (
                <ShiftCard key={s.id} index={i} shift={s} wp={wpById(s.workplaceId)} st={stById(s.workplaceId, s.shiftTypeId)}
                  onEdit={() => actions.edit(s)} onDuplicate={() => actions.duplicate(s)} onMenu={() => actions.menu(s)} />
              ))}
            </div>
          )}
          <button onClick={() => actions.add(sel, true)} style={{
            marginTop: 14, width: "100%", minHeight: 48, borderRadius: T.rBtn, cursor: "pointer",
            border: `1.5px dashed ${T.divider}`, background: "#fff", color: T.primary, fontFamily: T.font,
            fontSize: 15, fontWeight: 600, display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
          }}>
            <Plus size={18} /> הוספת משמרת ליום זה
          </button>
        </div>
      )}
    </div>
  );
}

/* ============================ Settings screen ============================ */
function SettingsScreen({ name, setName, workplaces, onEditWorkplace, onAddWorkplace, onBack }) {
  const [editingName, setEditingName] = useState(false);
  const [tmp, setTmp] = useState(name);
  return (
    <div style={{ padding: "8px 20px 120px" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginTop: 12, marginBottom: 18 }}>
        <button onClick={onBack} aria-label="חזרה" style={{ border: "none", background: "#fff", boxShadow: T.shadowSoft, borderRadius: 999, width: 40, height: 40, display: "grid", placeItems: "center", cursor: "pointer" }}>
          <ChevronRight size={22} color={T.text} />
        </button>
        <div style={{ fontSize: 26, fontWeight: 700 }}>הגדרות</div>
      </div>

      <div style={{ fontSize: 14, fontWeight: 600, color: T.text2, marginBottom: 10, marginInlineStart: 2 }}>פרופיל</div>
      <div style={{ background: "#fff", borderRadius: T.rCard, boxShadow: T.shadowSoft, padding: 6 }}>
        <div style={rowStyle}>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 12 }}><User size={20} color={T.text2} /> שם</span>
          {editingName ? (
            <span style={{ display: "flex", gap: 8 }}>
              <input value={tmp} onChange={(e) => setTmp(e.target.value)} autoFocus
                style={{ border: "none", background: "#F7F8FA", borderRadius: 10, padding: "6px 10px", fontFamily: T.font, fontSize: 16, width: 110, textAlign: "start" }} />
              <button onClick={() => { setName(tmp || name); setEditingName(false); }} style={{ border: "none", background: T.primary, color: "#fff", borderRadius: 10, width: 34, cursor: "pointer" }}><Check size={16} /></button>
            </span>
          ) : (
            <button onClick={() => { setTmp(name); setEditingName(true); }} style={{ border: "none", background: "none", cursor: "pointer", fontFamily: T.font, fontSize: 16, fontWeight: 600, color: T.text }}>{name}</button>
          )}
        </div>
        <div style={{ ...rowStyle, borderTop: `1px solid ${T.divider}` }}>
          <span>יום ראשון בשבוע</span><span style={{ color: T.text2 }}>ראשון</span>
        </div>
        <div style={{ ...rowStyle, borderTop: `1px solid ${T.divider}` }}>
          <span>פורמט שעות</span><span style={{ color: T.text2 }}>24 שעות</span>
        </div>
      </div>

      <div style={{ fontSize: 14, fontWeight: 600, color: T.text2, margin: "22px 2px 10px" }}>מקומות עבודה</div>
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {workplaces.map((w) => (
          <button key={w.id} onClick={() => onEditWorkplace(w)} style={{
            background: "#fff", borderRadius: T.rCard, boxShadow: T.shadowSoft, padding: "16px 18px",
            border: "none", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "space-between", fontFamily: T.font,
          }}>
            <span style={{ display: "flex", alignItems: "center", gap: 12 }}>
              <span style={{ width: 12, height: 12, borderRadius: 999, background: w.accent }} />
              <span style={{ textAlign: "start" }}>
                <div style={{ fontSize: 18, fontWeight: 600, color: T.text }}>{w.name}</div>
                <div style={{ fontSize: 13, color: T.text2 }}>{w.shiftTypes.length} סוגי משמרות</div>
              </span>
            </span>
            <ChevronLeft size={20} color={T.text2} />
          </button>
        ))}
      </div>
      <button onClick={onAddWorkplace} style={{
        marginTop: 14, width: "100%", minHeight: 50, borderRadius: T.rBtn, cursor: "pointer",
        border: `1.5px dashed ${T.divider}`, background: "#fff", color: T.primary, fontFamily: T.font,
        fontSize: 15, fontWeight: 600, display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
      }}>
        <Plus size={18} /> הוספת מקום עבודה
      </button>
    </div>
  );
}
const rowStyle = { display: "flex", alignItems: "center", justifyContent: "space-between", padding: "14px 14px", fontFamily: T.font, fontSize: 16, color: T.text };

/* ============================ Root App ============================ */
export default function App() {
  const [name, setName] = useState("");
  const [workplaces, setWorkplaces] = useState([]);
  const [shifts, setShifts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(null);

  const [tab, setTab] = useState("home");
  const [weekOffset, setWeekOffset] = useState(0);
  const [monthOffset, setMonthOffset] = useState(0);
  const [focusDay, setFocusDay] = useState(null);
  const [sheet, setSheet] = useState(null);   // {type, ...payload}
  const [closing, setClosing] = useState(false);

  // ---- Load everything from the Worker API on mount (single source of truth) ----
  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const state = await api.getState();
        if (!alive) return;
        setName(state?.profile?.name || "");
        setWorkplaces(Array.isArray(state?.workplaces) ? state.workplaces : []);
        setShifts(Array.isArray(state?.shifts) ? state.shifts : []);
        setLoadError(null);
      } catch (e) {
        if (!alive) return;
        // Offline / API unreachable: fall back to local defaults so the UI still works.
        setLoadError(e);
        setName("יוסי");
        setWorkplaces(seedWorkplaces());
        setShifts(seedShifts());
      } finally {
        if (alive) setLoading(false);
      }
    })();
    return () => { alive = false; };
  }, []);

  // ---- Persist the profile name (debounced), skipping the initial load ----
  const nameLoaded = useRef(false);
  useEffect(() => {
    if (loading) return;
    if (!nameLoaded.current) { nameLoaded.current = true; return; }
    const t = setTimeout(() => { api.saveProfile({ name }).catch(() => {}); }, 500);
    return () => clearTimeout(t);
  }, [name, loading]);

  const openSheet = (s) => { setClosing(false); setSheet(s); };
  const closeSheet = () => { setClosing(true); setTimeout(() => { setSheet(null); setClosing(false); }, 200); };

  // ---- Mutations: write to the API, then reflect the server response in state ----
  const saveShift = async (data) => {
    closeSheet();
    try {
      if (data.id && shifts.some((s) => s.id === data.id)) {
        const saved = await api.updateShift(data.id, data);
        setShifts((prev) => prev.map((s) => (s.id === saved.id ? saved : s)));
      } else {
        const saved = await api.createShift(data);
        setShifts((prev) => [...prev, saved]);
      }
    } catch (e) {
      // Best-effort: refetch to stay consistent with the server.
      api.listShifts().then(setShifts).catch(() => {});
    }
  };

  const deleteShift = async (id) => {
    closeSheet();
    const prev = shifts;
    setShifts((cur) => cur.filter((s) => s.id !== id)); // optimistic
    try {
      await api.deleteShift(id);
    } catch (e) {
      setShifts(prev); // revert on failure
    }
  };

  const duplicateShift = async (source, days) => {
    closeSheet();
    const payload = days.map((d) => ({
      workplaceId: source.workplaceId, shiftTypeId: source.shiftTypeId,
      start: source.start, end: source.end, date: d,
    }));
    try {
      const created = await api.bulkCreateShifts(payload);
      setShifts((prev) => [...prev, ...(Array.isArray(created) ? created : [])]);
    } catch (e) {
      api.listShifts().then(setShifts).catch(() => {});
    }
  };

  const saveWorkplace = async (wp) => {
    closeSheet();
    const existingIds = workplaces.map((w) => w.id);
    try {
      const saved = await api.saveWorkplace(wp, existingIds);
      setWorkplaces((prev) =>
        prev.some((w) => w.id === saved.id)
          ? prev.map((w) => (w.id === saved.id ? saved : w))
          : [...prev, saved]
      );
    } catch (e) {
      api.listWorkplaces().then(setWorkplaces).catch(() => {});
    }
  };

  const [now, setNow] = useState(new Date());
  useEffect(() => { const t = setInterval(() => setNow(new Date()), 30000); return () => clearInterval(t); }, []);

  const actions = {
    add: (date, fixed) => openSheet({ type: "shift", mode: "add", initial: date ? { date } : null, fixedDate: !!fixed }),
    edit: (s) => openSheet({ type: "shift", mode: "edit", initial: s }),
    duplicate: (s) => openSheet({ type: "duplicate", shift: s }),
    menu: (s) => openSheet({ type: "menu", shift: s }),
  };

  const NAV_MAX = 480;

  return (
    <div dir="rtl" className="app-root" style={{ minHeight: "100vh", width: "100%", maxWidth: "100%", overflowX: "hidden", background: "linear-gradient(180deg, #F3F7FF 0%, #F7F8FA 32%, #F7F8FA 100%)", fontFamily: T.font, color: T.text }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Rubik:wght@400;500;600;700&display=swap');
        html,body{margin:0;background:#F3F7FF;width:100%;max-width:100%;overflow-x:hidden;}
        html{-webkit-text-size-adjust:100%;}
        * { box-sizing: border-box; }
        img { max-width: 100%; }
        .app-root { width:100%; max-width:100%; overflow-x:hidden; }
        .noscroll::-webkit-scrollbar { display:none; }
        .noscroll { scrollbar-width: none; }
        .wheelcol::-webkit-scrollbar { display:none; }
        .wheelcol { scrollbar-width: none; }
        @keyframes sheetIn { from{transform:translateY(100%)} to{transform:translateY(0)} }
        @keyframes sheetOut { from{transform:translateY(0)} to{transform:translateY(100%)} }
        @keyframes fadeIn { from{opacity:0} to{opacity:1} }
        @keyframes fadeOut { from{opacity:1} to{opacity:0} }
        @keyframes cardIn { from{opacity:0;transform:translateY(10px)} to{opacity:1;transform:translateY(0)} }
        @keyframes revealIn { from{opacity:0;transform:translateY(8px)} to{opacity:1;transform:translateY(0)} }
        @keyframes titleFade { from{opacity:0;transform:translateY(-2px)} to{opacity:1;transform:translateY(0)} }
        @keyframes monthFwd { from{opacity:0;transform:translateX(-20px)} to{opacity:1;transform:translateX(0)} }
        @keyframes monthBack { from{opacity:0;transform:translateX(20px)} to{opacity:1;transform:translateX(0)} }
        @keyframes stepInLeft { from{opacity:0;transform:translateX(-16px)} to{opacity:1;transform:translateX(0)} }
        @keyframes stepInRight { from{opacity:0;transform:translateX(16px)} to{opacity:1;transform:translateX(0)} }
        @keyframes weekFwd { from{opacity:0;transform:translateX(-28px)} to{opacity:1;transform:translateX(0)} }
        @keyframes weekBack { from{opacity:0;transform:translateX(28px)} to{opacity:1;transform:translateX(0)} }
        @keyframes tabIn { from{opacity:0} to{opacity:1} }
        @keyframes spin { to{ transform: rotate(360deg) } }
        @media (prefers-reduced-motion: reduce){ *{animation:none!important;transition:none!important} }

        /* ===== HERO ===== */
        .hero {
          position: relative;
          z-index: 0;
          width: 100%;
          height: 420px;
          min-height: 420px;
          max-height: 420px;
          padding-inline: 24px;
          padding-top: 20px;
          overflow: hidden;
          box-sizing: border-box;
        }
        .settingsButton {
          position: absolute;
          top: 18px;
          left: 18px;
          z-index: 10;
          width: 48px;
          height: 48px;
          border: none;
          border-radius: 999px;
          background: rgba(255,255,255,0.85);
          backdrop-filter: blur(10px);
          box-shadow: 0 4px 20px rgba(17,24,39,0.05);
          display: grid;
          place-items: center;
          cursor: pointer;
        }
        .heroGrid {
          display: grid;
          grid-template-columns: 40% 60%;
          align-items: stretch;
          height: 100%;
          direction: rtl;
        }
        .greetingBlock {
          align-self: start;
          margin-top: 93px;
          text-align: right;
          width: 100%;
          max-width: 100%;
          padding-right: 4px;
          z-index: 2;
        }
        .greetingLine { font-size: 28px; font-weight: 700; line-height: 1.15; color: ${T.text}; }
        .dayGreeting { font-size: 26px; font-weight: 700; line-height: 1.15; color: ${T.text}; margin-top: 10px; }
        .greetingSubtitle { font-size: 16px; font-weight: 400; line-height: 1.5; color: ${T.text2}; margin-top: 10px; }
        .mascotWrapper {
          position: relative;
          z-index: 0;
          width: 100%;
          height: 100%;
          overflow: visible;
          box-sizing: border-box;
        }
        .mascotImage {
          position: absolute;
          bottom: -12px;
          right: 30px;
          display: block;
          width: auto;
          height: 380px;
          max-width: none;
          max-height: none;
          object-fit: contain;
          object-position: bottom center;
          filter: drop-shadow(0 10px 16px rgba(17,24,39,0.14));
        }

        /* ===== CURRENT SHIFT CARD ===== */
        .currentShiftCard {
          position: relative;
          z-index: 2;
          width: clamp(0px, 62%, calc(100% - 32px));
          min-width: min(250px, calc(100% - 32px));
          max-width: calc(100% - 32px);
          margin-inline-start: 16px;
          margin-inline-end: auto;
          margin-top: -160px;
          margin-bottom: 20px;
          height: auto;
          min-height: 0;
          padding: 14px 20px;
          border-radius: 26px;
          box-sizing: border-box;
          background: linear-gradient(165deg, #ffffff 0%, #fbfdff 100%);
          box-shadow: 0 14px 30px rgba(17,24,39,0.09), 0 2px 6px rgba(17,24,39,0.05);
          border: 1px solid rgba(255,255,255,0.6);
        }
        .cardTopRow {
          display: flex;
          align-items: flex-start;
          justify-content: flex-start;
          direction: rtl;
        }
        .statusStack {
          display: flex;
          flex-direction: column;
          align-items: flex-end;
          gap: 5px;
        }
        .statusBadge {
          display: inline-flex;
          align-items: center;
          gap: 6px;
          font-size: 14px;
          font-weight: 700;
          padding: 8px 12px;
          border-radius: 999px;
          white-space: nowrap;
        }
        .statusDot { width: 6px; height: 6px; border-radius: 999px; flex-shrink: 0; }
        .remainingText {
          font-size: 14px;
          font-weight: 600;
          white-space: nowrap;
          padding-inline-end: 4px;
        }
        .cardMainRow {
          margin-top: 10px;
          display: flex;
          justify-content: flex-start;
          direction: rtl;
        }
        .shiftInfo { width: 100%; text-align: right; }
        .shiftWorkplace { font-size: 27px; font-weight: 750; line-height: 1.1; margin: 0; color: ${T.text}; }
        .shiftMeta {
          margin-top: 8px;
          display: flex;
          align-items: center;
          justify-content: flex-start;
          flex-wrap: wrap;
          gap: 7px;
          direction: rtl;
          font-size: 16px;
          font-weight: 500;
          color: ${T.text2};
        }
        .shiftMeta .metaSep { color: ${T.divider}; }
        .shiftMeta .shiftTime { font-size: 19px; font-weight: 650; color: ${T.text}; }

        @media (max-width: 370px) {
          .greetingLine { font-size: 26px; }
          .dayGreeting { font-size: 24px; }
          .mascotImage { max-height: 380px; }
          .statusBadge, .remainingText { font-size: 13px; }
        }
      `}</style>

      {/* app column */}
      <div style={{ width: "100%", maxWidth: NAV_MAX, margin: "0 auto", minHeight: "100vh", position: "relative", overflowX: "hidden" }}>
        <div key={tab} style={{ paddingBottom: 130, animation: "tabIn .22s ease" }}>
          {loading ? (
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", minHeight: "70vh", gap: 14 }}>
              <div style={{ width: 34, height: 34, borderRadius: 999, border: `3px solid ${T.divider}`, borderTopColor: T.primary, animation: "spin .8s linear infinite" }} />
              <div style={{ fontSize: 14, color: T.text2 }}>טוען את המשמרות שלך…</div>
            </div>
          ) : (<>
          {tab === "home" && <Home name={name} workplaces={workplaces} shifts={shifts} weekOffset={weekOffset} setWeekOffset={setWeekOffset} focusDay={focusDay} setFocusDay={setFocusDay} actions={actions} now={now} onOpenSettings={() => setTab("settings")} />}
          {tab === "calendar" && <CalendarScreen workplaces={workplaces} shifts={shifts} monthOffset={monthOffset} setMonthOffset={setMonthOffset} actions={actions} />}
          {tab === "settings" && <SettingsScreen name={name} setName={setName} workplaces={workplaces} onBack={() => setTab("home")}
            onEditWorkplace={(w) => openSheet({ type: "workplace", workplace: w, isNew: false })}
            onAddWorkplace={() => openSheet({ type: "workplace", isNew: true, workplace: { id: "w" + Date.now(), name: "מקום חדש", accent: T.primary, shiftTypes: [] } })} />}
          </>)}
        </div>
      </div>

      {/* bottom nav: floating iOS-style pill */}
      <div style={{
        position: "fixed", bottom: "calc(18px + env(safe-area-inset-bottom, 0px))", left: "50%", transform: "translateX(-50%)",
        width: "calc(100% - 32px)", maxWidth: NAV_MAX - 32,
        height: 88, background: "rgba(255,255,255,0.78)", backdropFilter: "blur(24px) saturate(1.6)",
        WebkitBackdropFilter: "blur(24px) saturate(1.6)",
        borderRadius: 26, border: "1px solid rgba(255,255,255,0.6)",
        boxShadow: "0 16px 40px rgba(17,24,39,0.14), 0 2px 8px rgba(17,24,39,0.06)",
        display: "flex", alignItems: "center",
        justifyContent: "space-between", padding: "0 30px", zIndex: 20,
      }}>
        <NavTab icon={<LayoutList size={24} />} label="משמרות" active={tab === "home"} onClick={() => setTab("home")} />
        <div style={{ width: 64 }} />
        <NavTab icon={<CalendarDays size={24} />} label="לוח" active={tab === "calendar"} onClick={() => setTab("calendar")} />
      </div>

      {/* FAB */}
      <button onClick={() => actions.add(null)} aria-label="הוספת משמרת" style={{
        position: "fixed", bottom: "calc(28px + env(safe-area-inset-bottom, 0px))", left: "50%", transform: "translateX(-50%)", zIndex: 22,
        width: 68, height: 68, borderRadius: 999, background: T.primary, border: "5px solid #fff",
        boxShadow: "0 10px 26px rgba(22,119,255,0.45)", cursor: "pointer", display: "grid", placeItems: "center",
      }}>
        <Plus size={30} color="#fff" strokeWidth={2.4} />
      </button>

      {/* sheets */}
      {sheet?.type === "shift" && (
        <ShiftSheet mode={sheet.mode} initial={sheet.initial} fixedDate={sheet.fixedDate} workplaces={workplaces} shifts={shifts}
          onClose={closeSheet} closing={closing} onSave={saveShift} onDelete={deleteShift} />
      )}
      {sheet?.type === "menu" && (
        <ActionMenu onClose={closeSheet} closing={closing}
          onEdit={() => { const s = sheet.shift; closeSheet(); setTimeout(() => actions.edit(s), 210); }}
          onDuplicate={() => { const s = sheet.shift; closeSheet(); setTimeout(() => openSheet({ type: "duplicate", shift: s }), 210); }}
          onDelete={() => deleteShift(sheet.shift.id)} />
      )}
      {sheet?.type === "duplicate" && (
        <DuplicateSheet source={sheet.shift} workplaces={workplaces} onClose={closeSheet} closing={closing}
          onConfirm={(days) => duplicateShift(sheet.shift, days)} />
      )}
      {sheet?.type === "workplace" && (
        <WorkplaceInfoSheet workplace={sheet.workplace} isNew={sheet.isNew} shifts={shifts} onClose={closeSheet} closing={closing} onSave={saveWorkplace} />
      )}
    </div>
  );
}

function NavTab({ icon, label, active, onClick }) {
  return (
    <button onClick={onClick} style={{
      background: "none", border: "none", cursor: "pointer", display: "flex", flexDirection: "column",
      alignItems: "center", gap: 4, fontFamily: T.font, color: active ? T.primary : T.text2, width: 72,
    }}>
      {React.cloneElement(icon, { strokeWidth: 2 })}
      <span style={{ fontSize: 11, fontWeight: 600 }}>{label}</span>
    </button>
  );
}
